#!/bin/sh
# declaration lane -- swift -- generated by
# Research/op_pipeline/declare_lane.py .  Do not hand-edit.
# one tiny compile per type per form; no operator anywhere.
set -u
export HOME=/work
export PATH=/persist/swift/usr/bin:$PATH
export GOTOOLCHAIN=local
export GOPROXY=off
export GOFLAGS=-mod=mod
ROOT=/work/decl_swift
export GOCACHE="$ROOT/gocache"
export GOPATH="$ROOT/gopath"
# swift's binaries want libncurses.so.6 and the image ships
# only libncursesw.so.6.6; the symlink lives in the image's
# own /usr/lib and does NOT survive a container restart.
if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
  ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
     /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
  ldconfig 2>/dev/null
fi
echo "=== declaration lane -- swift -- 34 declarations ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! /persist/swift/usr/bin/swiftc --version >/dev/null 2>&1; then
  echo "!! REFUSING TO START: swiftc is not runnable in this container."
  exit 4
fi
/persist/swift/usr/bin/swiftc --version 2>&1 | head -2
rm -rf "$ROOT"; mkdir -p "$ROOT" "$GOCACHE" "$GOPATH"
mkdir -p "$ROOT/u"
base64 -d <<'T_EOF' | gunzip > "$ROOT/table.json"
H4sIAAAAAAAC/62XzWqDQBSFX2VwlUJoHDVTGyiFUkr7AHbTFJnoJAgTFaNpS8i715/SRTow1nuy
kfGaw8cH3pOcHC3zXSN3ylkx5/CRbWtnzpyiqbvzor0uUpXouJ9c15/9NKvV/tDO307mb2fp73FR
f5Uqdru7h1JpneW7bvZQFLq7ty2qfXc+yiqTG63654qmSvrAstnoLGHbJk9YRyErlb5K3ajZFTut
c9Z+tKpZfFyxLvCe3bE808Mgbg/xcZ2f17lznjMYaSkruVe1quyoz4VOVTWLmRz4fqE7NvlvNH6J
9lg0P8pgGodIhMgRtBNVDkFEmd4l3pMuZA112SciVNpZJ5rsc4gifSMcF3iVXCBkjuGl6OSCKDQw
AoYuXmjoIoSO4aUIDV2i0OUl4EuOfdHbPIRIG+dEiW0KUaAwgHEvRDtsIxEaR9BON9kGEWXemPAE
3CVkV9pZCSapezI0wPkeWqTvIUTaWaeL9D2iyFsDnAjQIkWAEGlnnS5SBNQf6K6BDr4mIUvSjjrd
I3VD8j9/HSJ0Y0egyrajTtQY0VubeyY2dG9HuOIeBUzwSe9u7hsJBd4opL7H4FJ8UhucByY+cIdH
sBIfg0vQSe5xvjTxgZs8glX5GFyCTnqbCxMffntidqcdluDSvDffz9+SfQodPRYAAA==
T_EOF
echo "payload bytes: $(wc -c < "$ROOT/table.json")"
python3 - "$ROOT" <<'PY_EOF'

# --- verbatim delimiter codec, copied from verbatim_diag.py ---
def esc(text):
    """make `text` safe to place in one pipe-delimited field, reversibly."""
    for raw, rep in _ENC:
        text = text.replace(raw, rep)
    return text

_ENC = [('\\', '\\\\'), ('|', '\\p'), (';', '\\s'), ('\n', '\\n'), ('\r', '\\r')]
MARKER = '#verbatim-escape v1'

import json
import os
import subprocess
import sys

ROOT = sys.argv[1]
TABLE = json.load(open(os.path.join(ROOT, "table.json")))
LANG = TABLE["language"]
OUT = TABLE["out"]
WORK = os.path.join(ROOT, "u")

CLANG = "/usr/bin/clang"
CLANGXX = "/usr/bin/clang++"
SWIFTC = "/persist/swift/usr/bin/swiftc"
GOMOD = "module declprobe\n\ngo 1.26\n"


def sh(cmd, cwd=None, timeout=300):
    try:
        p = subprocess.run(cmd, cwd=cwd, timeout=timeout,
                           stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.TimeoutExpired:
        return 124, "", "TIMEOUT after %ds" % timeout
    so = p.stdout.decode("utf-8", "replace")
    se = p.stderr.decode("utf-8", "replace")
    return p.returncode, so, se


def compile_one(source, d):
    if LANG == "c":
        src = os.path.join(d, "decl.c")
        open(src, "w").write(source)
        cmd = [CLANG, "-std=c17", "-O0", "-g", "-c", src,
               "-o", os.path.join(d, "decl.o")]
        rc, so, se = sh(cmd)
        return rc, (se or so)
    if LANG == "cpp":
        src = os.path.join(d, "decl.cpp")
        open(src, "w").write(source)
        cmd = [CLANGXX, "-std=c++20", "-O0", "-g", "-c", src,
               "-o", os.path.join(d, "decl.o")]
        rc, so, se = sh(cmd)
        return rc, (se or so)
    if LANG == "rust":
        src = os.path.join(d, "decl.rs")
        open(src, "w").write(source)
        cmd = ["rustc", "--crate-type=lib", "--emit=obj",
               "-C", "opt-level=0", "-g",
               "-o", os.path.join(d, "decl.o"), src]
        rc, so, se = sh(cmd)
        return rc, (se or so)
    if LANG == "go":
        open(os.path.join(d, "go.mod"), "w").write(GOMOD)
        open(os.path.join(d, "main.go"), "w").write(source)
        cmd = ["go", "build", "-gcflags=-N -l", "-o",
               os.path.join(d, "decl_bin"), "."]
        rc, so, se = sh(cmd, cwd=d)
        return rc, (se or so)
    if LANG == "swift":
        src = os.path.join(d, "decl.swift")
        open(src, "w").write(source)
        cmd = [SWIFTC, "-Onone", "-g", "-c", src,
               "-o", os.path.join(d, "decl.o")]
        rc, so, se = sh(cmd)
        return rc, (se or so)
    raise KeyError(LANG)


out = open(OUT, "w")
out.write(MARKER + '\n')
tally = {"submitted": 0, "accept": 0, "refuse": 0}
n = 0
for item in TABLE["items"]:
    n = n + 1
    d = os.path.join(WORK, "d%05d" % n)
    subprocess.run(["rm", "-rf", d])
    os.makedirs(d)
    rc, diag = compile_one(item["source"], d)
    tally["submitted"] = tally["submitted"] + 1
    if rc == 0:
        tally["accept"] = tally["accept"] + 1
        verdict = "ACCEPT"
    else:
        tally["refuse"] = tally["refuse"] + 1
        verdict = "REFUSE"
    out.write("%s|%s|%s|%s\n" % (esc(item["id"]), esc(item["form"]),
                                 verdict, esc(diag.strip())))
    out.flush()
    subprocess.run(["rm", "-rf", d])
    if n % 25 == 0:
        print("  %d of %d" % (n, len(TABLE["items"])))
        sys.stdout.flush()

out.close()
print("done: %s -> %s" % (json.dumps(tally), OUT))

PY_EOF
echo "--- lane finished, rc=$?"
date -u +%Y-%m-%dT%H:%M:%SZ
